{
  "scenario_id": "s7af96630b1",
  "rule": "controller_force_limit",
  "explanation": "Body1 (high speed) collides with controlled Body0 at step 28 (gap 0.005 in touching_pairs). The collision impulse abruptly changes Body0 velocity from ~2.9 m/s to ~10.27 m/s. On the next control update (step 29), the velocity-error law kp*(vcmd - v) produces ~486 N, exceeding declared fmax 72.67 N. The controller force is not clamped to fmax after collision correction, or collision impulse is incorrectly added to controller force accumulation. substeps_in_step stays high (23 then 19) indicating many substeps during contact.",
  "citations": [
    {"step": 28, "body": 0, "field": "speed", "value": 2.9080937464537344, "claim": "controlled body speed just before collision, touching gap near zero"},
    {"step": 28, "body": -1, "field": "speed", "value": 0.0051825762655755, "claim": "gap shows bodies 0 and 1 almost touching/colliding"},
    {"step": 29, "body": 0, "field": "speed", "value": 10.27091271082136, "claim": "speed spikes after collision impulse"},
    {"step": 29, "body": -1, "field": "energy", "value": 486.87506276319675, "claim": "controller_force at first violation 486.875 > fmax 72.674 at step 29"}
  ],
  "counterfactual": {
    "scenario_id": "s744a24479c",
    "change": "Removed the colliding second body (bodies array from 2 to 1). Without collision, controller force stays within limit for same 29 steps, proving collision-induced velocity change caused the force limit breach."
  }
}
